// secp256k1 public-key recovery "compute-and-commit" side-car library. Mirrors keccak-compute-library.ts, but the
// recovery is a PAIR of co-spent side-cars: A runs the GLV ladder to a checkpoint and commits it; B continues from the
// checkpoint to the recovered pubkey and commits the COMPRESSED key (33 B) to its recreated NFT. The covenants are
// signature-INDEPENDENT (they read (hash,v,r,s) + the GLV witnesses off the stack and self-verify), so hash256(covA)
// and hash256(covB) are compile-time constants the contract bakes for the side-car integrity check. See
// packages/solidc/docs/ecrecover.md. The recovery engine is proven in ecrecover-poc/engine.mjs; the deployable
// covenant hexes below are generated from ecrecover-poc/gen-ecrecover-sidecar.mjs (the blob-structured commit-tail
// production build). Redeem = OP_PUSHBYTES_32 || salt(32) || COVENANT (salt = the consuming contract's category).
import { hash256 } from './hash.js';
import type { Artifact } from './artifact.js';

export const ECRECOVER_COMPUTE_A_COVENANT =
  '';
export const ECRECOVER_COMPUTE_B_COVENANT =
  '';

/** hash256(covenant A); baked into the contract's side-car integrity check. */
export const ECRECOVER_COMPUTE_A_COVENANT_HASH =
  '0e6ad08337679310e1c839e7c8ac2bc6e26842c12950902d04471af8b7e6c628';
/** hash256(covenant B); baked into the contract's side-car integrity check. */
export const ECRECOVER_COMPUTE_B_COVENANT_HASH =
  '6f6bd6af198773eb73c61c7bc3bc26c878f77818c3e37595a2f9219dac67a68f';

/** Redeem salt-push prefix: OP_PUSHBYTES_32 (0x20) + 32 salt bytes. The covenant begins after this offset. */
export const ECRECOVER_COMPUTE_SALT_PREFIX_LENGTH = 33;

/** Op-budget pad (bytes) the SDK puts in each recovery side-car unlocking so its input funds ~half the GLV ladder. */
export const ECRECOVER_COMPUTE_PAD_LENGTH = 8000;

const hexToBytes = (h: string): Uint8Array => Uint8Array.from(h.match(/.{2}/g)!.map((b) => parseInt(b, 16)));

/** Build a recovery side-car redeem: OP_PUSHBYTES_32 || salt(32) || COVENANT (role 'A' checkpoint | 'B' pubkey). */
export function buildEcrecoverComputeRedeem(salt: Uint8Array, role: 'A' | 'B'): Uint8Array {
  if (salt.length !== 32) throw new Error('ecrecover compute side-car salt must be 32 bytes');
  const cov = hexToBytes(role === 'A' ? ECRECOVER_COMPUTE_A_COVENANT : ECRECOVER_COMPUTE_B_COVENANT);
  return Uint8Array.from([0x20, ...salt, ...cov]);
}

/** P2SH32 locking bytecode for a recovery side-car: OP_HASH256 <hash256(redeem)> OP_EQUAL. */
export function ecrecoverComputeLockingBytecode(salt: Uint8Array, role: 'A' | 'B'): Uint8Array {
  return Uint8Array.from([0xaa, 0x20, ...hash256(buildEcrecoverComputeRedeem(salt, role)), 0x87]);
}

/**
 * P2SH32 locking bytecode (35 B: OP_HASH256 <hash> OP_EQUAL) of the SHARED-salt A / B recovery side-cars. A dynamic
 * ecrecover loop verifies each pair's integrity with OP_UTXOBYTECODE == this constant (a cheap 35-byte compare)
 * instead of re-reading + hash256-ing the ~7.4 KB / ~3.3 KB covenant every iteration, which exhausted the master's
 * op-budget at ~3 iterations. Computed from the covenant at load, so they track any covenant change. Loop side-cars
 * are always shared-salt (branding is not needed for soundness: the argBlob bind + A->B hash chain secures the result).
 */
export const ECRECOVER_COMPUTE_A_SHARED_LOCK = ecrecoverComputeLockingBytecode(new Uint8Array(32), 'A');
export const ECRECOVER_COMPUTE_B_SHARED_LOCK = ecrecoverComputeLockingBytecode(new Uint8Array(32), 'B');

/** The result-NFT commitment for a recovery: parity byte (0x02/0x03) || Qx as a 33-byte LE VM number (34 B total). */
export function ecrecoverComputeResultCommitment(recoveredPubkey: Uint8Array): Uint8Array {
  if (recoveredPubkey.length !== 34) throw new Error('recovered pubkey commitment must be 34 bytes (parity || Qx-LE)');
  return recoveredPubkey;
}

/**
 * The minimum recovery side-car pairs a contract needs deployed at creation, read from its compiled artifact.
 * Each ecrecoverPubKey call co-spends one A+B pair; `pairs` = the largest single function's call count.
 */
export function ecrecoverSideCarRequirement(artifact: Artifact): { pairs: number } | undefined {
  const fns = artifact.abi.filter((f) => f.ecrecoverCompute);
  if (fns.length === 0) return undefined;
  const pairs = Math.max(...fns.map((f) => (f.ecrecoverArgParams?.length ?? 1)));
  return { pairs };
}
